          try: R`اعمل الفولدرات والملفات، وشغّل [[composer dump-autoload]]، وافتح [[public/index.php]]. بعدين غيّر اسم الملف لـ [[postController.php]] (p صغيرة): على ويندوز هيشتغل، وعلى سيرفر Linux هيقع بـ [[Class not found]].`,
